284	/// The run-deadline future: a durable timer of `timeout_ms`, or a never-
285	/// resolving future when no deadline is configured.
286	async fn run_deadline(ctx: &WorkflowContext<DurableAgentWorkflow>, timeout_ms: Option<u64>) {
287	    match timeout_ms {
288	        Some(ms) => {
289	            let _ = ctx.timer(Duration::from_millis(ms)).await;
290	        }
291	        None => futures_util::future::pending::<()>().await,
292	    }
293	}
