295	/// Execute driver effects one activity at a time until the driver reports a
296	/// terminal outcome.
297	async fn run_effects(
298	    ctx: &WorkflowContext<DurableAgentWorkflow>,
299	    config: &WorkflowActivityConfig,
300	    agent_name: &str,
301	    ctx_seed: &Option<serde_json::Value>,
302	    parallel_limit: Option<usize>,
303	    driver: &mut DurableDriver,
304	) -> DurableRunOutcome {
305	    loop {
306	        match driver.next_effect() {
307	            DriverEffect::RenderInstructions => {
308	                match ctx
309	                    .start_activity(
310	                        AgentActivities::render_instructions,
311	                        (agent_name.to_owned(), ctx_seed.clone()),
312	                        config.instructions_activity_opts.clone(),
313	                    )
314	                    .await
315	                {
316	                    Ok(system_text) => driver.apply_instructions(system_text),
317	                    // An infra-level failure of the (otherwise deterministic)
318	                    // render step is terminal — surface it like a model
319	                    // failure so the run finalizes with events-so-far.
320	                    Err(err) => driver.apply_model_failure(extract_error_kind(&err)),
321	                }
322	            }
323	            DriverEffect::CallModel(request) => {
324	                match ctx
325	                    .start_activity(
326	                        AgentActivities::call_model,
327	                        (agent_name.to_owned(), request),
328	                        config.model_activity_opts.clone(),
329	                    )
330	                    .await
331	                {
332	                    Ok(turn) => driver.apply_model(turn),
333	                    // ADR-10: `call_model` marks model errors non-retryable and
334	                    // carries an `ErrorKindPayload` JSON in the failure — parse
335	                    // it back and feed the terminal failure to the driver.
336	                    Err(err) => driver.apply_model_failure(extract_error_kind(&err)),
337	                }
338	            }
339	            DriverEffect::ExecuteTools(calls) => {
340	                let outcomes =
341	                    execute_tools(ctx, config, agent_name, ctx_seed, parallel_limit, calls).await;
342	                driver.apply_tools(outcomes);
343	            }
344	            DriverEffect::Finished(outcome) => return outcome,
345	        }
346	    }
347	}
