349	/// Execute one turn's tool calls, started concurrently and chunked by
350	/// `parallel_limit`, returning the outcomes **in original call order** (the
351	/// driver reassembles tool results by position, not by completion order).
352	async fn execute_tools(
353	    ctx: &WorkflowContext<DurableAgentWorkflow>,
354	    config: &WorkflowActivityConfig,
355	    agent_name: &str,
356	    ctx_seed: &Option<serde_json::Value>,
357	    parallel_limit: Option<usize>,
358	    calls: Vec<ToolCallRequest>,
359	) -> Vec<ToolCallOutcome> {
360	    // `None`/`0` ⇒ no concurrency cap: one chunk of every call.
361	    let chunk_size = parallel_limit
362	        .filter(|&n| n > 0)
363	        .unwrap_or_else(|| calls.len().max(1));
364	
365	    let mut outcomes = Vec::with_capacity(calls.len());
366	    for chunk in calls.chunks(chunk_size) {
367	        let started = chunk.iter().map(|call| {
368	            let call = call.clone();
369	            let call_id = call.call_id.clone();
370	            let opts = config.tool_activity_opts.clone();
371	            let agent_name = agent_name.to_owned();
372	            let ctx_seed_cloned = ctx_seed.clone();
373	            async move {
374	                match ctx
375	                    .start_activity(
376	                        AgentActivities::invoke_tool,
377	                        (agent_name, call, ctx_seed_cloned),
378	                        opts,
379	                    )
380	                    .await
381	                {
382	                    Ok(outcome) => outcome,
383	                    // Tool-level errors are already `Ok(ToolCallOutcome{ result:
384	                    // Err(..) })`. Reaching an `Err` here means the activity
385	                    // itself failed at the infra level (e.g. exhausted retries,
386	                    // unregistered agent). Fold it into a tool-error outcome so
387	                    // the loop stays total and the model sees a tool failure —
388	                    // Task 9 validates the live crash-resume path.
389	                    Err(err) => ToolCallOutcome {
390	                        call_id,
391	                        result: Err(format!(
392	                            "tool activity failed: {}",
393	                            activity_failure_message(&err)
394	                        )),
395	                    },
396	                }
397	            }
398	        });
399	        // `join_all` preserves input order in its result `Vec` (deterministic).
400	        let chunk_outcomes = temporalio_sdk::workflows::join_all(started).await;
401	        outcomes.extend(chunk_outcomes);
402	    }
403	    outcomes
404	}
